function verifiedPathDisplay(row) {
  const unavailable = (status, label, reason) => ({status, label, code:"INSUFFICIENT", delta:null,
    explanation:reason + "；数据完整度不是预测准确率；未改变冻结记录或模型输入"});
  if (!row || row.path_evidence_verified !== true) return unavailable("UNVERIFIED", "待核验", "路径来源尚未通过日期、成员及SHA校验");
  const numeric = value => value === null || value === undefined || String(value).trim() === "" ? null :
    (Number.isFinite(Number(value)) ? Number(value) : null);
  const days = numeric(row.path_days_observed), coverage = numeric(row.path_data_coverage);
  const latest = numeric(row.path_strength_latest), delta = numeric(row.path_strength_delta);
  const expected = row.stage_transition === "2→3" ? 2 : row.stage_transition === "3→4" ? 3 : null;
  if (!expected || days !== expected) return unavailable("INCOMPLETE", "数据不足", "连续连板日观测不完整，不能跨缺失日期比较");
  if (coverage === null || coverage < 1-1e-9 || coverage > 1) return unavailable("INCOMPLETE", "数据不足", "四项核心指标未逐日齐全；旧评分可能因缺项重新分配权重，暂停强弱判断");
  const previous = latest === null || delta === null ? null : latest-delta;
  if (latest === null || delta === null || latest < 0 || latest > 1 || previous < -1e-9 || previous > 1+1e-9)
    return unavailable("INVALID", "待核验", "强度或变化值超出有效范围");
  if (!(row.path_label_code in PRIMARY_PATH_LABELS) || row.path_label !== PRIMARY_PATH_LABELS[row.path_label_code] || row.path_label_code === "INSUFFICIENT")
    return unavailable("INVALID", "待核验", "路径标签与观测证据不一致");
  // Independent descriptive overlay. Never write these labels back into frozen/model rows.
  // Slopes are FIRST-to-LAST endpoints per board, whereas strength_delta is LAST-two boards.
  const dimensions = [
    {key:"path_gap_slope", name:"开盘缺口", sign:1, band:.005, unit:100, suffix:"个百分点", up:"抬升", down:"下移"},
    {key:"path_first_seal_slope", name:"首封时刻", sign:-1, band:10, unit:1, suffix:"时钟分钟", up:"提前", down:"推迟"},
    {key:"path_open_times_slope", name:"炸板次数", sign:-1, band:.5, unit:1, suffix:"次", up:"减少", down:"增加"},
    {key:"path_seal_ratio_slope", name:"封单/成交额", sign:1, band:.02, unit:100, suffix:"个百分点", up:"增加", down:"减少"}
  ].map(item => ({...item, value:numeric(row[item.key])}));
  if (dimensions.some(item => item.value === null))
    return unavailable("INCOMPLETE", "数据不足", "分项变化证据缺失；不能用综合分差代替多维判断");
  const span = expected-1;
  if (Math.abs(dimensions[1].value*span)>335+1e-9 ||
      Math.abs(dimensions[2].value*span-Math.round(dimensions[2].value*span))>1e-6)
    return unavailable("INVALID", "待核验", "首封时刻或炸板次数变化超出日汇总口径");
  const classify = scale => {
    const votes = dimensions.map(item => {
      const change=item.value*span*item.sign;
      return Math.abs(change)<item.band*scale-1e-9 ? 0 : Math.sign(change);
    });
    const up=votes.filter(value=>value>0).length, down=votes.filter(value=>value<0).length;
    // Conflict takes priority; a higher aggregate score cannot override contrary evidence.
    return {kind:up&&down?"MIXED":up>=2?"UP":down>=2?"DOWN":"LIMITED",up,down};
  };
  const base=classify(1), stable=[.75,1.25].every(scale=>classify(scale).kind===base.kind);
  const labels={MIXED:"多维分化",UP:"多维增强",DOWN:"多维减弱",LIMITED:"变化有限"};
  const evidence=dimensions.map(item=>{
    const change=item.value*span, direction=Math.abs(change)<item.band ? "小幅/持平" :
      (change*item.sign>0 ? item.up : item.down);
    return `${item.name}${direction}（首末差 ${change>0?"+":""}${(change*item.unit).toFixed(2)}${item.suffix}）`;
  }).join("；");
  const turnover=numeric(row.path_turnover_slope), amount=numeric(row.path_amount_log_slope);
  const participation=(turnover===null||amount===null) ? "量能辅助证据不足，不据此判断承接。" :
    `换手率首末差 ${(turnover*span).toFixed(2)}个百分点、成交额对数差 ${(amount*span).toFixed(3)}；放量不自动等于承接强。`;
  return {status:stable?"MULTIDIMENSION_DESCRIPTION":"BOUNDARY_SENSITIVE", version:"path-description-v2",
    label:stable?labels[base.kind]:"方向待判", code:stable?base.kind:"BOUNDARY", delta, direction:stable?base.kind:"BOUNDARY",
    change_text:stable?`增强${base.up} / 减弱${base.down}`:"边界待判",
    evidence_count:4, threshold_stable:stable,
    explanation:`D日及之前${expected}个连板日，四项核心日汇总齐全。首末板比较：${evidence}。`+
      (expected===3?"首末差不代表中间一天同向，不能证明持续加速。":"")+
      `${participation}增强/减弱为四项中达到描述阈值的项数，其余为小幅/持平；不是样本数或概率。相邻两板旧规则分：${(previous*100).toFixed(2)} → ${(latest*100).toFixed(2)}，分差不是涨幅或概率。`+
      "描述阈值：开盘0.5个百分点、首封10时钟分钟、炸板0.5次、封单比2个百分点；"+
      (stable?"阈值上下浮动25%时分类一致。":"阈值上下浮动25%时分类改变，暂停方向结论。")+
      "首封比较是时刻先后，不是扣除午休的封板耗时；日汇总不能证明逐笔封单、连续封板或真实承接。"+
      "高开不等于更值得买入；数据完整、方向一致和阈值稳定均不是预测准确率。未改变模型输入、排名或交易规则。"};
}

function pathChangePoints(value) {
