// Independent read-only monthly route. Reuses the exact deployment's
// validators; never recalculates ranks, trade outcomes or frozen features.
function ledgerStatus(row) {
  if (row.status === "POSTHOC_SUPPLEMENT_NOT_FORMAL") return {kind:"supplement", label:"事后补录"};
  if (row.status === "SETTLED_1000_LIMIT_HOLD_MINUTE_PROXY") return {kind:"settled", label:"已结算"};
  if (row.status.startsWith("NO_FILL_")) return {kind:"no-fill", label:"未买入"};
  if (row.status.includes("LIMIT_UP")) return {kind:"holding", label:"封板延持"};
  if (row.status.startsWith("MISSING_") || /MISSING|UNRESOLVED/.test(row.status)) return {kind:"missing", label:"待补数据"};
  return {kind:"pending", label:row.status === "PENDING_T" ? "等待买入日" : "待结算"};
}

function ledgerPerformance(rows) {
  const settled = rows.filter(r => ledgerStatus(r).kind === "settled");
  const count = kind => rows.filter(r => ledgerStatus(r).kind === kind).length;
  const wins = settled.filter(r => r.slot_net_return > 0).length;
  return {count:rows.length, settled:settled.length, wins, noFill:count("no-fill"),
    holding:count("holding"), pending:count("pending"), missing:count("missing"),
    winRate:settled.length ? wins / settled.length : null,
    mean:settled.length ? settled.reduce((sum,r) => sum+r.slot_net_return,0)/settled.length : null};
}

function ledgerFilter(rows, month, slot, status, query) {
  const needle = query.trim().toLowerCase();
  return rows.filter(row => row.signal_date.slice(0,6) === month
    && (!slot || String(row.slot) === slot) && (!status || ledgerStatus(row).kind === status)
    && (!needle || `${row.ts_code || ""} ${row.name || ""}`.toLowerCase().includes(needle)))
    .sort((a,b) => a.signal_date.localeCompare(b.signal_date) || a.slot-b.slot);
}

function ledgerCsv(rows) {
  const columns = [["signal_date","D日期"],["slot","盈利名次"],["ts_code","代码"],["name","名称"],
    ["industry","行业"],["stage_transition","晋级"],["path_label","连板路径"],["promotion_rank","晋级排序"],
