    ["actual_exit_date","退出日"],["actual_exit_time","退出时间"],["exit_price","卖出价"],["slot_net_return","扣费收益比例"],["supplement_note","补录说明"],["detail_error","详情校验提示"]];
  const cell = value => {
    let text = value == null ? "" : String(value);
    if (typeof value === "string" && /^[=+\-@\t\r]/.test(text)) text = "'" + text;
    return '"'+text.replaceAll('"','""')+'"';
  };
  return "\ufeff" + [columns.map(c=>cell(c[1])).join(","), ...rows.map(row=>columns.map(([key])=>
    cell(key === "slot_net_return" && ledgerStatus(row).kind !== "settled" ? null : row[key])).join(","))].join("\r\n");
}

function ledgerCanonicalSource(bytes) {
  // Preserve Python-emitted number tokens (e.g. 1e-07 and 0.0) rather
  // than round-tripping through JS Number before checking the ledger hash.
  const tokens = new TextDecoder().decode(bytes).match(/"(?:[^"\\]|\\.)*"|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false|null|[{}\[\],:]/g) || [];
  let position=0;
  const quoted = token => JSON.stringify(JSON.parse(token)).replace(/[\u007f-\uffff]/g,
    c=>"\\u"+c.charCodeAt(0).toString(16).padStart(4,"0"));
  function value() {
    const token=tokens[position++];
    if(token === "{") {
      const pairs=[];
      while(tokens[position] !== "}") {
        const key=tokens[position++];executableProfitExpect(key?.startsWith('"') && tokens[position++] === ":", "冻结JSON对象无效");
        pairs.push([JSON.parse(key),quoted(key)+":"+value()]);
        if(tokens[position]!==",")break;position++;
      }
      executableProfitExpect(tokens[position++] === "}", "冻结JSON对象未闭合");
      return "{"+pairs.sort((a,b)=>a[0]<b[0]?-1:a[0]>b[0]?1:0).map(p=>p[1]).join(",")+"}";
    }
    if(token === "[") {
      const parts=[];
      while(tokens[position]!=="]") {parts.push(value());if(tokens[position]!==",")break;position++;}
      executableProfitExpect(tokens[position++] === "]", "冻结JSON列表未闭合");
      return "["+parts.join(",")+"]";
    }
    executableProfitExpect(token !== undefined, "冻结JSON值缺失");
    return token.startsWith('"') ? quoted(token) : token;
  }
  const result=value();executableProfitExpect(position===tokens.length,"冻结JSON尾部无效");return result;
}

async function ledgerJoinDay(date, sequences, navigation) {
  const sourceRows = sequences.map(rows => rows.find(r=>r.signal_date===date));
  executableProfitExpect(sourceRows.every(Boolean), "盈1/盈2逐日记录缺失");
  if (sourceRows.every(r=>r.status === "MISSING_D_PUBLICATION")) {
    const missing = sourceRows.map((r,i)=>({...r,slot:i+1}));
    if (date !== "20260921") return missing;
    const entry = navigation.find(r=>r.signal_date===date);
    if (!entry) return missing;
    const {wrapper} = await loadPublishedDailyEntry(entry);
    const view = candidateUnifiedProfitView(validatedThreeRankContract(wrapper));
    if (!view.ready || !view.supplement) return missing;
    return missing.map((r,i)=>{
      const selected = [...view.rows].find(([,score])=>score.executable_profit_research_rank===i+1);
      executableProfitExpect(selected, "补录席位缺失");
      const identity = wrapper.three_rank.rows.find(row=>row.ts_code===selected[0]);
      executableProfitExpect(identity, "补录股票身份缺失");
      return {...r,ts_code:identity.ts_code,name:identity.name,industry:identity.industry,
        stage_transition:identity.stage_transition,promotion_rank:identity.promotion_rank,
        status:"POSTHOC_SUPPLEMENT_NOT_FORMAL",formal_status:r.status,
        exec_date:null,entry_price:null,entry_price_source:null,actual_exit_date:null,
        actual_exit_time:null,exit_price:null,slot_net_return:null,
        supplement_note:"2026-09-22事后补算；非原盘前发布，不计正式成绩。未补造买入、退出及收益。"};
    });
  }
  const entry = navigation.find(r=>r.signal_date===date);
  executableProfitExpect(entry, "缺少同D冻结名单目录");
  const {wrapper, runtimeIndex} = await loadPublishedDailyEntry(entry);
  const frozen = await loadCandidateProfitDay(wrapper);
  const frozenEntry = state.candidateProfitActivation.index.days.find(r=>r.signal_date===date);
  const originalBytes = await fetchPagesOnlyShaBoundJson(frozenEntry.path,frozenEntry.sha256,"当日冻结原文件");
  const projectionHash = await sha256Hex(new TextEncoder().encode(ledgerCanonicalSource(originalBytes.bytes)));
  const rows = sourceRows.map((r,i) => {
    const slot = i+1, original = frozen.projection.candidate_slots[i];
    executableProfitExpect(r.slot === slot && r.formal_projection_sha256 === projectionHash
      && r.snapshot_file_sha256 === frozen.projection.snapshot_file_sha256
      && ["ts_code","candidate_rank","candidate_score","promotion_rank"].every(key=>r[key]===original[key])
      && r.exec_date === frozen.projection.exec_date && r.exit_date === frozen.projection.exit_date,
      "账本与当日冻结席位不一致");
    const identity = frozen.projection.rows.find(x=>x.ts_code===r.ts_code);
    const promotion = wrapper.three_rank.rows.find(x=>x.ts_code===r.ts_code);
    if (!identity) {
      executableProfitExpect(r.status === "MISSING_CANDIDATE", "冻结股票身份缺失");
      return {...r, slot};
    }
    return {...r,slot,name:identity.name,industry:identity.industry,stage_transition:promotion.stage_transition};
  });
  try {
    const path = await loadCurrentThreeRankPathEvidence(wrapper,runtimeIndex);
    return rows.map(r=>{const display=verifiedPathDisplay(path.rows.find(x=>x.ts_code===r.ts_code));return {...r,path_label:display.label,path_explanation:display.explanation};});
  } catch(error) {
    return rows.map(r=>({...r,path_label:"待校验",detail_error:`连板路径：${error.message}`}));
  }
}

